// === FORMAT NOTIFIKASI PAGI (Most Active + Rekomendasi Intraday) ===
// ⚠️ GANTI nomor ini dengan nomor WA tujuan kamu (format 62xxxxxxxxxx)
const NOMOR_TUJUAN = 'GANTI-DENGAN-NOMOR-WA';

const BATAS_KARAKTER_WA = 3500;
function splitPesan(pesan, batas = BATAS_KARAKTER_WA) {
  if (pesan.length <= batas) return [pesan];
  const hasil = [];
  let sisa = pesan;
  while (sisa.length > batas) {
    let potong = sisa.lastIndexOf('\n', batas);
    if (potong <= 0) potong = batas;
    hasil.push(sisa.slice(0, potong));
    sisa = sisa.slice(potong);
  }
  if (sisa.length > 0) hasil.push(sisa);
  return hasil;
}

function rp(angka) {
  if (angka === undefined || angka === null || angka === '') return 'N/A';
  return `Rp${Number(angka).toLocaleString('id-ID')}`;
}

function formatJumlah(angka) {
  if (angka === undefined || angka === null || angka === '') return '-';
  if (angka >= 1e9) return `${(angka / 1e9).toFixed(1)} M`;
  if (angka >= 1e6) return `${(angka / 1e6).toFixed(1)} jt`;
  return Number(angka).toLocaleString('id-ID');
}

const rawInput = $input.first().json;
const inputHttp = rawInput || {};
const gagal = Boolean(inputHttp.error) || inputHttp.status !== 'success';

if (gagal) {
  const e = inputHttp.error || {};
  const detailError = inputHttp.detail || e.message || e.description || (typeof inputHttp.error === 'string' ? inputHttp.error : '') || 'Server tidak merespons.';
  const pesan = `⚠️ *Notifikasi pagi gagal.*\n${detailError}\n\nPeriksa endpoint /v1/pasar/digest-pagi.`;
  return [{ json: { pesan_wa: pesan, to: NOMOR_TUJUAN } }];
}

const data = inputHttp.data || inputHttp;

let t = `🌅 *DIGEST PAGI SAHAM*${data.tanggal_data ? ` (per ${data.tanggal_data})` : ''}\n`;
t += `━━━━━━━━━━━━━━━━━━━━\n`;
t += `Analisis: ${data.jumlah_saham_dianalisis} saham BEI\n\n`;

// --- MOST ACTIVE ---
const ma = data.most_active || {};
t += `🔥 *MOST ACTIVE (Top 10)*\n`;
(ma.list || []).forEach((m, i) => {
  const pct = (m.pct_change_hari !== null && m.pct_change_hari !== undefined)
    ? `${m.pct_change_hari > 0 ? '+' : ''}${m.pct_change_hari}%` : '-';
  t += `${i + 1}. *${m.ticker}* — ${rp(m.harga)} (${pct})\n`;
  t += `   Vol: ${formatJumlah(m.volume)} | Nilai: Rp${(m.nilai_transaksi / 1e9).toFixed(1)} M\n`;
});

// --- REKOMENDASI INTRADAY ---
const ri = data.rekomendasi_intraday || {};
t += `\n⚡ *REKOMENDASI INTRADAY* (kandidat likuid ≥ Rp5 M)\n`;
t += `Berhasil diskor: ${ri.jumlah_saham_berhasil || 0}/${ri.jumlah_saham_diproses || 0}\n\n`;
(ri.leaderboard_per_strategi_intraday || []).forEach((lb) => {
  t += `📌 *${lb.nama}*\n`;
  const best = lb.terbaik || [];
  if (best.length === 0) {
    t += `   (tidak ada saham ber-skor)\n\n`;
  } else {
    best.forEach((f) => {
      const sy = f.sinyal_aktif ? ' ✅ aktif' : ' ⏸ standby';
      t += `   • *${f.ticker}* — skor ${f.skor}${sy}\n`;
    });
    t += `\n`;
  }
});

// --- PERINGATAN ---
if (ma.peringatan) t += `⚠️ ${ma.peringatan}\n`;
if (ri.peringatan) t += `⚠️ ${ri.peringatan}\n`;

t += `\n💡 *Aksi lanjut:* ketik *scan <TICKER> strategi* untuk detail, atau *scan <TICKER> bpjs/bsjp* untuk eksekusi harian.\n`;
t += `📌 _Data hari trading terakhir (anti look-ahead). Bukan ajakan beli — terapkan manajemen risiko._`;

return splitPesan(t).map((p) => ({ json: { pesan_wa: p, to: NOMOR_TUJUAN } }));
